package com.astrocare.controller; import com.astrocare.dto.*; import com.astrocare.service.MarkerService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/anatomy/markers") @RequiredArgsConstructor @PreAuthorize("hasRole('FLIGHT_SURGEON')") public class AnatomyController {private final MarkerService service; @GetMapping public List<MarkerResponse> list(@RequestParam Long astronautId){return service.list(astronautId);} @PostMapping public MarkerResponse create(@Valid @RequestBody MarkerRequest r,Authentication a){return service.create(r,a.getName());}}
